// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SaleContract) predicate.SaleContract {
	return predicate.SaleContract(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SaleContract) predicate.SaleContract {
	return predicate.SaleContract(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SaleContract) predicate.SaleContract {
	return predicate.SaleContract(sql.NotPredicates(p))
}
